// ---------- Fake seams ----------

type fakeProcessChecker struct {
	alive map[int]bool
}

func (f fakeProcessChecker) Alive(pid int) bool {
	if f.alive == nil {
		return false
	}
	return f.alive[pid]
}

type fakeTmuxChecker struct {
	sessions map[string]bool
}

func (f fakeTmuxChecker) HasSession(name string) bool {
	if f.sessions == nil {
		return false
	}
	return f.sessions[name]
}

