		t.Fatal(err)
	}
	// Commit feature metadata so repo stays clean
	gitInDir(t, dir, "add", "-A")
	gitInDir(t, dir, "commit", "-m", "add feature")

	// Create feat-branch from current HEAD so it's current with main
	gitInDir(t, dir, "branch", "feat-branch")

